Mesh visible_mesh(){Mesh q;q.positions={{-.75f,-.75f,.02f},{.75f,-.75f,-.03f},{.75f,.75f,.06f},{-.75f,.75f,-.02f}};q.normals={normalized(Vec3{.1f,-.2f,1}),normalized(Vec3{.35f,.15f,1}),normalized(Vec3{-.25f,.4f,1}),normalized(Vec3{-.3f,-.1f,1})};q.uv={{{0,0}},{{1,0}},{{1,1}},{{0,1}}};q.indices={0,1,2,0,2,3};Mesh out;for(auto i:q.indices){out.indices.push_back(uint32_t(out.positions.size()));out.positions.push_back(q.positions[i]);out.normals.push_back(q.normals[i]);out.uv.push_back(q.uv[i]);}return out;}
