struct Basis{Vec3 tangent,bitangent;};
Basis independent_basis(const Mesh &mesh,size_t triangle,const std::vector<std::array<float,2>> &uv,Vec3 normal){const auto a=mesh.indices[triangle*3],b=mesh.indices[triangle*3+1],c=mesh.indices[triangle*3+2];const auto p=mesh.positions[b]-mesh.positions[a],q=mesh.positions[c]-mesh.positions[a];const float du=uv[b][0]-uv[a][0],dv=uv[b][1]-uv[a][1],eu=uv[c][0]-uv[a][0],ev=uv[c][1]-uv[a][1],det=du*ev-eu*dv;auto tangent=(p*ev-q*dv)/det,raw_b=(q*du-p*eu)/det;tangent=normalized(tangent-normal*dot(tangent,normal));return{tangent,cross(normal,tangent)*(dot(cross(normal,tangent),raw_b)<0?-1.f:1.f)};}
