 if((argc==9||argc==10)&&std::string_view(argv[1])=="--visible-control"){if(argc==10&&std::string_view(argv[9])!="--without-baked-detail")throw std::invalid_argument("Unknown independent control variant");source8_public::visible_control(argv[2],argv[3],std::stoi(argv[4]),std::stoi(argv[5]),std::stoi(argv[6]),std::stoul(argv[7]),argv[8],argc==10);return 0;}
 throw std::invalid_argument("source8-public-fixture --public-fixtures DIRECTORY | --inspect FILE | --visible-control MANIFEST desktop|xr WIDTH HEIGHT EYE PROBE OUTPUT [--without-baked-detail]");
